# Mutações da 243a leva (itens cpf_1, cpf_2, cpf_3, cpg_1, cpg_2, cpg_3, cph_1). Uso: python mutacoes.py mutacoes\leva243.py --carreira 2002-06-01
MUTACOES = [
    ('cpf_nota_byte', '*((this + 0x1c) as *mut u8) = *((origem + 0x1c) as *const u8); // o byte do recorde de nota', '*((this + 0x1c) as *mut u8) = 0; // mutacao: o byte zerado'),
    ('cpf_melhor_vezes', '*(this as *mut u8) = *(origem as *const u8); // as vezes de melhor em campo', '*(this as *mut u8) = (*(origem as *const u8)).wrapping_add(1); // mutacao: uma vez a mais'),
    ('cpf_disciplina_vermelhos', '*((this + 1) as *mut u8) = *((origem + 1) as *const u8); // os vermelhos', '*((this + 1) as *mut u8) = *(origem as *const u8); // mutacao: os amarelos no lugar'),
    ('cpf_contagem', 'core::ptr::write_unaligned(this as *mut u16, core::ptr::read_unaligned(origem as *const u16)); // a contagem', 'core::ptr::write_unaligned(this as *mut u16, core::ptr::read_unaligned(origem as *const u16).wrapping_add(1)); // mutacao: uma a mais'),
    ('cpf_torcedor_ano', 'core::ptr::write_unaligned((this + 0x18) as *mut u16, core::ptr::read_unaligned((origem + 0x18) as *const u16)); // o ano do torcedor', 'core::ptr::write_unaligned((this + 0x18) as *mut u16, 0); // mutacao: o ano zerado'),
    ('cpf_ocorrencias_data', 'init_default_date(this + 0x11); // a data das ocorrências', 'init_default_date(this + 0x10); // mutacao: a data um byte antes'),
    ('cpf_contagem_data', 'init_default_date(this + 0x12); // a data da contagem', 'init_default_date(this + 0x11); // mutacao: a data um byte antes'),
    ('cpf_valor_troca', '*((this + 0x28) as *mut u8) = *((origem + 0x28) as *const u8); // a marca de troca', '*((this + 0x28) as *mut u8) = 1; // mutacao: sempre troca'),
    ('cpf_gols', '*(this as *mut u8) = *(origem as *const u8); // os gols', '*(this as *mut u8) = (*(origem as *const u8)).wrapping_add(1); // mutacao: um gol a mais'),
    ('cpg_noticia_fichas', 'for k in 0..50 {\n        d(5 + 4 * k); // as fichas da notícia', 'for k in 0..49 {\n        d(5 + 4 * k); // mutacao: sem a ultima ficha'),
    ('cpg_passada_duplas', 'for k in 0..7 {\n        core::ptr::write_unaligned((this + 4 * k) as *mut u32, core::ptr::read_unaligned((origem + 4 * k) as *const u32)); // as duplas da transferência', 'for k in 0..6 {\n        core::ptr::write_unaligned((this + 4 * k) as *mut u32, core::ptr::read_unaligned((origem + 4 * k) as *const u32)); // mutacao: sem a ultima'),
    ('cpg_futura_oferta', 'core::ptr::write_unaligned((this + 8) as *mut u32, core::ptr::read_unaligned((origem + 8) as *const u32)); // o índice da oferta', 'core::ptr::write_unaligned((this + 8) as *mut u32, 0); // mutacao: a primeira oferta'),
    ('cpg_fila_pessoa', 'core::ptr::write_unaligned(this as *mut u32, core::ptr::read_unaligned(origem as *const u32)); // a pessoa do regen', 'core::ptr::write_unaligned(this as *mut u32, core::ptr::read_unaligned(origem as *const u32).wrapping_add(1)); // mutacao: a pessoa seguinte'),
    ('cpg_observados', '(p as u32 & !0xff) | (p != 0) as u32', '(p as u32 & !0xff) | 0 // mutacao: nunca esta'),
    ('cpg_doador_zero', 'if s > melhor && s > 0 { // a melhor da nação', 'if s > melhor && s >= 0 { // mutacao: aceita nota zero'),
    ('cpg_suspensao_bits', '*m = (*m & !7) | (*((origem + 0x13) as *const u8) & 7); // as três marcas', '*m = (*m & !7) | (*((origem + 0x13) as *const u8) & 3); // mutacao: so duas marcas'),
    ('cpg_salario_minimo', '*((this + 0xc) as *mut i32) = if v < 0x37 { 0x37 } else { v }; // o mínimo de 55', '*((this + 0xc) as *mut i32) = if v < 0x38 { 0x38 } else { v }; // mutacao: minimo 56'),
    ('cpg_condicao_porcento', 'return match_pl_ftol(c as f64 * *(0x96bac8 as *const f32) as f64) as u16; // em porcento', 'return (ftol(c as f64 * *(0x96bac8 as *const f32) as f64) - 1) as u16; // mutacao: um ponto a menos'),
    ('cph_dias_fim', 'dias(this + 0x2d, read_u32(G_CURRENT_DATE), read_u32(G_CURRENT_DATE_LEAP)) // a data do fim do contrato', 'dias(this + 0x25, read_u32(0xae2c90), read_u32(0xae2c94)) // mutacao: a data de inicio'),
    ('cph_queixas_zero', 'core::ptr::write_unaligned((this + 0x45) as *mut u32, 0); // as queixas', '*((this + 0x45) as *mut u8) = 0; // mutacao: so o byte baixo'),
    ('cph_retirada_moral', '*((this + 0x44) as *mut u8) = read_u8(pessoa + staff::PROFESSIONALISM).wrapping_add(read_u8(pessoa + staff::LOYALITY)).wrapping_add(5);', '*((this + 0x44) as *mut u8) = read_u8(pessoa + staff::PROFESSIONALISM).wrapping_add(read_u8(pessoa + staff::LOYALITY)).wrapping_add(4); // mutacao'),
    ('cph_retirada_felicidade', '*((this + 0x3d) as *mut u8) = 15; // a felicidade mínima', '*((this + 0x3d) as *mut u8) = 14; // mutacao: 14'),
]
